<script setup>
import {reactive,ref,watch} from 'vue'
import {onLoad,onShow,onHide,onUnload} from '@dcloudio/uni-app'
import {operatorSession,operatorToken,clearOperatorSession} from '../../services/operator-session.js'
import {createAsyncDiagnosisApi,initialDiagnosisState,createAsyncDiagnosisFlow,CASE_STATES} from '../../services/async-diagnosis.js'
import {imageRequestKey} from '../../services/private-images.js'
import {displayTime} from '../../services/reservations.js'
const queue=ref(false),handlerPage=ref(1),choices=ref({}),state=reactive(initialDiagnosisState()),api=createAsyncDiagnosisApi(),allowed=()=>queue.value?operatorSession.canDiagnoseManage:operatorSession.canDiagnose
const flow=createAsyncDiagnosisFlow({state,token:operatorToken,allowed,scope:()=>`diagnosis-${queue.value?'queue':'mine'}`,newKey:imageRequestKey,load:async(t,p)=>({cases:await api.list(t,'admin',p,queue.value),handlers:queue.value?await api.handlers(t,handlerPage.value):null}),write:(t,a,id,b,k)=>api.write(t,'admin',a,id,b,k),onWritten:()=>{choices.value={}},confirm:a=>new Promise(resolve=>uni.showModal({title:a==='close'?'关闭本次留言':'确认分配诊断人员',content:a==='close'?'关闭后不能追加或回复，既有内容按权限保留。':'只有当前获派且有诊断处理权限的人员可读取正文；转派后原人员失去读取与回复权限。',success:r=>resolve(r.confirm),fail:()=>resolve(false)}))})
let visible=false;function reset(){flow.reset();choices.value={}}function tab(value){if(state.busy||state.retry)return;queue.value=value}function login(){clearOperatorSession();uni.navigateTo({url:'/pages/operator/login'})}
function assign(c){const target=choices.value[c.case_id];if(!state.data?.handlers.items.some(h=>h.id===target)){state.message='请先选择当前页有效诊断人员。';return}flow.save('assign',c.case_id,{expected_revision:c.revision,operator_id:target})}
function handlers(p){handlerPage.value=p;choices.value={};flow.load(state.page)}
watch(()=>[operatorSession.accessToken,operatorSession.canDiagnose,operatorSession.canDiagnoseManage,queue.value],()=>{reset();if(visible&&operatorToken()&&allowed())flow.load()},{flush:'sync'})
onLoad(q=>{if(q?.scope==='queue')queue.value=true});
onShow(()=>{visible=true;if(!operatorSession.canDiagnose&&operatorSession.canDiagnoseManage)queue.value=true;if(operatorToken()&&allowed())flow.load()});onHide(()=>{visible=false;reset()});onUnload(()=>{visible=false;reset()})
watch(()=>state.kind,k=>{if(['unauthorized','forbidden','missing'].includes(k)){choices.value={}}})
</script>
<template><view class="reservation-page"><text class="reservation-title">诊断处理工作区</text><button @tap="uni.navigateTo({url:'/pages/diagnosis/notifications?role=admin'})">诊断站内消息</button><text>管理队列只含状态和分配信息；正文必须由获派且有处理权限的人员进入“分配给我”读取。</text><button v-if="!operatorToken()" @tap="login">运营登录</button><button v-if="operatorSession.canDiagnose" :disabled="state.busy||state.retry" @tap="tab(false)">分配给我</button><button v-if="operatorSession.canDiagnoseManage" :disabled="state.busy||state.retry" @tap="tab(true)">管理分配队列</button><text v-if="!allowed()">当前账号无此诊断工作区权限。</text><text v-if="state.message">{{state.message}}</text><button v-if="['unauthorized','forbidden'].includes(state.kind)" @tap="login">重新登录</button><button v-if="state.retry" :disabled="state.busy" @tap="flow.retry">重试原操作</button><button :disabled="state.busy" @tap="flow.load(state.page)">刷新</button><template v-if="state.data"><text v-if="!state.data.cases.items.length">当前范围暂无诊断记录。</text><view v-for="c in state.data.cases.items" :key="c.case_id" class="reservation-panel"><text>诊断记录 {{c.case_id}} · {{CASE_STATES[c.status]}} · {{displayTime(c.updated_at)}}</text><template v-if="queue"><text>{{c.assigned_operator_id?'已有诊断人员':'尚未分配'}}</text><template v-if="c.status!=='CLOSED'"><picker :range="state.data.handlers.items.map(h=>h.label)" :disabled="state.busy||state.retry" @change="choices[c.case_id]=state.data.handlers.items[Number($event.detail.value)]?.id"><view>{{state.data.handlers.items.find(h=>h.id===choices[c.case_id])?.label||'选择本页诊断人员'}}</view></picker><button :disabled="state.busy||state.retry" @tap="assign(c)">确认分配或转派</button><button :disabled="state.busy||state.retry" @tap="flow.save('close',c.case_id,{expected_revision:c.revision})">关闭此留言</button></template></template><button v-else @tap="uni.navigateTo({url:`/pages/diagnosis/detail?role=admin&id=${c.case_id}`})">按当前分配查看正文</button></view><template v-if="queue"><text>可选人员第 {{handlerPage}} 页</text><button v-if="handlerPage>1" :disabled="state.busy||state.retry" @tap="handlers(handlerPage-1)">上一页人员</button><button v-if="handlerPage*20<state.data.handlers.total" :disabled="state.busy||state.retry" @tap="handlers(handlerPage+1)">下一页人员</button></template><button v-if="state.page>1" :disabled="state.busy" @tap="flow.load(state.page-1)">上一页留言</button><button v-if="state.page*20<state.data.cases.total" :disabled="state.busy" @tap="flow.load(state.page+1)">下一页留言</button></template></view></template>
